      { name: "II ეტაპის — არქიტექტურული პროექტისა და კონსტრუქციული სქემის შეთანხმების", days: 20, opts: ["10 სამუშაო დღე", "15 სამუშაო დღე", "20 სამუშაო დღე", "30 სამუშაო დღე"], corr: 2, art: "მუხლი 22" },
      { name: "III ეტაპის — მშენებლობის ნებართვის გაცემის (სტანდარტული III/IV კლასის ობიექტზე)", days: 10, opts: ["5 სამუშაო დღე", "10 სამუშაო დღე", "20 სამუშაო დღე", "30 სამუშაო დღე"], corr: 1, art: "მუხლი 24" },
      { name: "I კლასის შენობა-ნაგებობის მშენებლობის თაობაზე მარტივი შეტყობინების განხილვის", days: 5, opts: ["3 სამუშაო დღე", "5 სამუშაო დღე", "10 სამუშაო დღე", "15 სამუშაო დღე"], corr: 1, art: "მუხლი 14" }
