      ref: "დადგენილება №354, თერმული ხიდები და კონდენსაციის პრევენცია",
      exp: "თერმული ხიდი არღვევს თბოსაიზოლაციო კონტურის უწყვეტობას, აცივებს შიდა ზედაპირს ნამის წერტილამდე და იწვევს კონდენსაციასა და ენერგოდანაკარგს."
