      exp: "რკინაბეტონის ფილა კარგად აკავებს ჰაეროვან ხმაურს, მაგრამ ადვილად ატარებს დარტყმით ვიბრაციას, რის გამოც მოჭიმვის (სტიაჟკის) ქვეშ ეწყობა დრეკადი აკუსტიკური საფენი."
