        exp: "ტექნიკური რეგლამენტი №476 უპირველესად არეგულირებს უსაფრთხოებისთვის კრიტიკულ პროდუქტებს: ცემენტი, არმატურა, კაბელები, პლასტმასის მილები და სხვ."
