    // პარამეტრული 1: პანდუსის ჰორიზონტალური პროექციის (სიგრძის) გაანგარიშება (თავი IV)
    const riseCm = randChoice([30, 40, 45, 50, 60, 75]);
    const slopeDenom = 12; // 1:12
    const runMeters = roundTo((riseCm * slopeDenom) / 100, 2);
    const numRamp = makeNumericOptions(runMeters, "მ", 0.60, 2);
