      chapter_tag: "732_ch4",
      q: `დადგენილება №732-ის (თავი IV, პანდუსები) თანახმად, თუ შესასვლელი ბაქნის სიმაღლეთა სხვაობა შეადგენს H = ${riseCm} სმ-ს (${(riseCm / 100).toFixed(2)} მ) და პანდუსი ეწყობა სტანდარტული მაქსიმალური ქანობით 1:12 (8.33%), რა იქნება პანდუსის დახრილი მარშის მინიმალური ჰორიზონტალური სიგრძე (ბაქნების გარეშე)?`,
