    const Sik = roundTo(K1 * A_seis * beta * eta * Qk, 1);
    const numSeis = makeNumericOptions(Sik, "კნ", 18, 1);
    items.push({
      q: `პნ 01.01-09-ის თანახმად, გამოთვალეთ k წერტილში თავმოყრილი Q_k = ${Qk} კნ წონის მასაზე მოქმედი საანგარიშო სეისმური ძალა S_ik = K₁ × A × β_i × η_ik × Q_k (როდესაც K₂=1, K_ψ=1, γ_n=1), თუ მოცემულია: დაზიანების დასაშვები კოეფიციენტი K₁ = ${K1}, სეისმური აჩქარების კოეფიციენტი A = ${A_seis}, დინამიურობის კოეფიციენტი β_i = ${beta} და ფორმის კოეფიციენტი η_ik = ${eta}:`,
      opts: numSeis.options,
      corr: numSeis.correct,
      ref: "პნ 01.01-09, მუხლი 5.2 (სეისმური დატვირთვის განსაზღვრა სპექტრული მეთოდით)",
      exp: `S_ik = ${K1} × ${A_seis} × ${beta} × ${eta} × ${Qk} = ${Sik.toFixed(1)} კნ.`
    });

