  // ============================================================================
  // საჯარო API (QuestionGenerator)
  // ============================================================================
  const QuestionGenerator = {
    /**
     * აბრუნებს მოცემული ქვეთავის ყველა უნიკალური კითხვის/პარამეტრული შაბლონის
     * ახლად დაგენერირებულ მასივს (დუბლირების გარეშე!)
     */
    generateSubchapterPool: function(subId) {
      const builder = SUBCHAPTER_BUILDERS[subId];
      if (!builder) return [];
      return builder();
    },

    generateArchitectureQuestion: function(subId) {
      const pool = this.generateSubchapterPool(subId);
      return pool.length > 0 ? randChoice(pool) : null;
    },

    generateStructuralQuestion: function(subId) {
      const pool = this.generateSubchapterPool(subId);
      return pool.length > 0 ? randChoice(pool) : null;
    }
  };

  window.QuestionGenerator = QuestionGenerator;
